import{describe,it,expect,beforeEach,vi}from"vitest";import{MultilingualAudioEngine}from"../../frontend/js-modules/multilingual-audio-engine.js";describe("Multilingual Audio Engine",()=>{let e,t;beforeEach(()=>{void 0===globalThis.SpeechSynthesisUtterance&&(globalThis.SpeechSynthesisUtterance=class{constructor(e){this.text=e,this.rate=1,this.lang="en-IN"}}),e={speak:vi.fn(),cancel:vi.fn(),getVoices:vi.fn().mockReturnValue([])},t=new MultilingualAudioEngine({speechSynth:e})}),it("should retrieve phonetic transliteration and native script for regional terms",()=>{const e=t.getPronunciation("Mekhela Chador");expect(e.phonetic).toBe("Meh-kheh-la Cha-dor"),expect(e.script).toBe("মেখেলা চাদৰ"),expect(e.lang).toBe("as-IN")}),it("should trigger speech synthesis when speak() is called",()=>{const i=t.speak("Pithla Bhakri");expect(i).toBe(!0),expect(e.speak).toHaveBeenCalledOnce()}),it("should fall back safely when speech synth is unavailable",()=>{const e=new MultilingualAudioEngine({speechSynth:null}).speak("Axone");expect(e).toBe(!1)})});